function evalEnvExp(k, type) {
    switch (type) {
        case 'string': return evalEnvExpStr(k);
        case 'number': return evalEnvExpNum(k);
        case 'array': return evalEnvExpArr(k);
        case 'boolean': return evalEnvExpBool(k);
        case 'undefined': return evalEnvExpAny(k);
        default: throw error(`unknown env exp type "${type}"`);
    }
}
function evalEnvExpAny(k) {
    let val = env.get(k);

    if (typeof val === 'string') {
        if (val.startsWith('%')) {
            val = contextEnvExp(val);
        }
    }

    return val;
}
function evalEnvExpBool(k) {
    let val = env.get(k);

    if (typeof val === 'string') {
        if (val.startsWith('%')) {
            val = contextEnvExp(val);
        }
    }

    if(typeof val !== 'boolean') throw error(`"${k}" must be a bool`);
    return val;
}
function evalEnvExpStr(k) {
    let val = env.get(k);

    if (typeof val === 'string') {
        if (val.startsWith('%')) {
            val = contextEnvExp(val);
        }
    }

    if(typeof val !== 'string') throw error(`"${k}" must be a string`);
    return val;
}
function evalEnvExpNum(k) {
    let val = env.get(k);

    if (typeof val === 'string') {
        if(val.startsWith('%')) {
            val = contextEnvExp(val);
        }
        if(typeof val === 'string') {
            val = val.replace(',', '.');
        }
    }

    val = parseFloat(val);
    if(Number.isNaN(val)) throw error(`"${k}" must be a number`);
    return val;
}
function evalEnvExpArr(k) {
    let val = env.get(k);

    if (typeof val === 'string') {
        if(!val) {
            val = []; 
        }
        else if (val.startsWith('%')) {
            val = contextEnvExp(val);
            if(!val) {
                val = [];
            }
        }

        if(typeof val === 'string') {
            val = val.split(',').map(x => x.trim());
        }
    }

    if(!isArr(val)) throw error(`"${k}" must be an array`);
    return val;
}
