function handleResponse(obj) {
    switch(obj.__type) {
        case 'ConnectResponse:#Bizerba.ConnectService': {
            let has_handle = obj.Response && obj.Response.startsWith('Q|');
            switch(obj.Status) {
                case 0: {
                    // handle or last data to receive
                    if(!has_handle) {
                        msg.result = msg.result || [];
                        msg.result.push(obj.Response);
                    }

                    return false;
                }
                case 1: {
                    // timeout
                    throw new Error(`timeout exceeded ${msg.args.timeout}`);
                }
                case 2: {
                    // data to receive
                    if (has_handle) {
                        msg.handle = obj.Response;
                    } else {
                        msg.result = msg.result || [];
                        msg.result.push(obj.Response);
                    }

                    return true
                }
                default: {
                    throw new Error(`unknown status "${obj.Status}" for "${obj.__type}"`);
                }
            }
        }
        break;

        case 'ConnectDeviceInfoBasic:#Bizerba.ConnectService': {
            msg.result = msg.result || [];
            msg.result.push(obj);
            return false;
        }
        break;

        case 'ConnectDeviceInfo:#Bizerba.ConnectService': {
            msg.result = msg.result || [];
            msg.result.push(obj);
            return false;
        }
        break;

        default: {
